<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Auth,Request,Response};
use App\Services\{AuditService,NumberService,ActivityService,UploadService,EventService};
final class InvoiceController extends Controller {
    public function index(): void {
        if(!Auth::can('invoice.view')){$this->forbidden();return;}$db=Database::connection();$t=Auth::tenantId();$db->prepare("UPDATE invoices SET status='Overdue',updated_at=NOW() WHERE tenant_id=? AND deleted_at IS NULL AND status IN('Sent','Partial') AND due_date<CURDATE() AND balance>0")->execute([$t]);$s=$db->prepare("SELECT i.*,c.name customer_name FROM invoices i JOIN customers c ON c.id=i.customer_id AND c.tenant_id=i.tenant_id WHERE i.tenant_id=? AND i.deleted_at IS NULL ORDER BY i.id DESC");$s->execute([$t]);$c=$db->prepare("SELECT id,name FROM customers WHERE tenant_id=? AND deleted_at IS NULL ORDER BY name");$c->execute([$t]);$scalar=function(string $sql,array $a)use($db){$x=$db->prepare($sql);$x->execute($a);return $x->fetchColumn();};$kpi=['outstanding'=>(float)$scalar("SELECT COALESCE(SUM(balance),0) FROM invoices WHERE tenant_id=? AND deleted_at IS NULL AND status IN('Sent','Partial','Overdue')",[$t]),'due_today'=>(float)$scalar("SELECT COALESCE(SUM(balance),0) FROM invoices WHERE tenant_id=? AND deleted_at IS NULL AND due_date=CURDATE() AND balance>0",[$t]),'overdue'=>(float)$scalar("SELECT COALESCE(SUM(balance),0) FROM invoices WHERE tenant_id=? AND deleted_at IS NULL AND status='Overdue'",[$t]),'paid_month'=>(float)$scalar("SELECT COALESCE(SUM(amount),0) FROM payments WHERE tenant_id=? AND YEAR(payment_date)=YEAR(CURDATE()) AND MONTH(payment_date)=MONTH(CURDATE())",[$t])];$aging=$db->prepare("SELECT SUM(CASE WHEN DATEDIFF(CURDATE(),due_date) BETWEEN 0 AND 30 THEN balance ELSE 0 END) a0_30,SUM(CASE WHEN DATEDIFF(CURDATE(),due_date) BETWEEN 31 AND 60 THEN balance ELSE 0 END) a31_60,SUM(CASE WHEN DATEDIFF(CURDATE(),due_date) BETWEEN 61 AND 90 THEN balance ELSE 0 END) a61_90,SUM(CASE WHEN DATEDIFF(CURDATE(),due_date)>90 THEN balance ELSE 0 END) a90plus FROM invoices WHERE tenant_id=? AND deleted_at IS NULL AND balance>0");$aging->execute([$t]);$pp=$db->prepare("SELECT pp.*,i.invoice_number,c.name customer_name FROM customer_payment_proofs pp JOIN invoices i ON i.id=pp.invoice_id AND i.tenant_id=pp.tenant_id JOIN customers c ON c.id=i.customer_id AND c.tenant_id=i.tenant_id WHERE pp.tenant_id=? AND pp.status='Pending' ORDER BY pp.id DESC");$pp->execute([$t]);$this->view('invoices/index',['title'=>'Invoices & Accounts Receivable','invoices'=>$s->fetchAll(),'customers'=>$c->fetchAll(),'kpi'=>$kpi,'aging'=>$aging->fetch(),'paymentProofs'=>$pp->fetchAll()]);
    }
    public function show(string $id): void {if(!Auth::can('invoice.view')){$this->forbidden();return;}$db=Database::connection();$t=Auth::tenantId();$s=$db->prepare("SELECT i.*,c.name customer_name,c.email customer_email,c.phone customer_phone,c.billing_address,j.job_number,q.quotation_number FROM invoices i JOIN customers c ON c.id=i.customer_id AND c.tenant_id=i.tenant_id LEFT JOIN jobs j ON j.id=i.job_id AND j.tenant_id=i.tenant_id LEFT JOIN quotations q ON q.id=i.quotation_id AND q.tenant_id=i.tenant_id WHERE i.id=? AND i.tenant_id=? AND i.deleted_at IS NULL");$s->execute([(int)$id,$t]);$invoice=$s->fetch();if(!$invoice){http_response_code(404);require BASE_PATH.'/app/Views/errors/404.php';return;}$it=$db->prepare("SELECT * FROM invoice_items WHERE invoice_id=? AND tenant_id=? ORDER BY id");$it->execute([(int)$id,$t]);$p=$db->prepare("SELECT p.*,u.name user_name FROM payments p LEFT JOIN users u ON u.id=p.created_by WHERE p.invoice_id=? AND p.tenant_id=? ORDER BY p.id DESC");$p->execute([(int)$id,$t]);$this->view('invoices/show',['title'=>$invoice['invoice_number'],'invoice'=>$invoice,'items'=>$it->fetchAll(),'payments'=>$p->fetchAll()]);}
    public function store(): void {$this->requireCsrf();if(!Auth::can('invoice.create'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$t=(int)Auth::tenantId();$customer=(int)Request::input('customer_id');$items=$_POST['items']??[];if(!$customer||!is_array($items)||!$items)Response::json(['success'=>false,'message'=>'Customer dan item invoice wajib.','errors'=>[]],422);$subtotal=0;$discount=0;$tax=0;$clean=[];foreach($items as $r){$desc=trim((string)($r['description']??''));$qty=(float)($r['quantity']??0);$price=(float)($r['unit_price']??0);$disc=(float)($r['discount']??0);$tx=(float)($r['tax']??0);if($desc===''||$qty<=0)continue;$line=max(0,$qty*$price-$disc+$tx);$subtotal+=$qty*$price;$discount+=$disc;$tax+=$tx;$clean[]=[$desc,$qty,$r['unit']??'unit',$price,$disc,$tx,$line];}if(!$clean)Response::json(['success'=>false,'message'=>'Item invoice tidak valid.','errors'=>[]],422);$total=max(0,$subtotal-$discount+$tax);$db=Database::connection();$num=NumberService::next($t,'invoice','INV');$db->beginTransaction();try{$db->prepare("INSERT INTO invoices(tenant_id,invoice_number,customer_id,invoice_date,due_date,subtotal,discount,tax,total,paid,balance,status,created_by,created_at,updated_at) VALUES(?,?,?,CURDATE(),?,?,?,?,?,0,?,'Draft',?,NOW(),NOW())")->execute([$t,$num,$customer,Request::input('due_date')?:date('Y-m-d',strtotime('+14 days')),$subtotal,$discount,$tax,$total,$total,Auth::id()]);$iid=(int)$db->lastInsertId();$ins=$db->prepare("INSERT INTO invoice_items(tenant_id,invoice_id,description,quantity,unit,unit_price,discount,tax,line_total) VALUES(?,?,?,?,?,?,?,?,?)");foreach($clean as $r)$ins->execute([$t,$iid,...$r]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}$ce=$db->prepare("SELECT email FROM customers WHERE id=? AND tenant_id=?");$ce->execute([$customer,$t]);AuditService::log('create','invoice',$iid,null,['invoice_number'=>$num,'total'=>$total]);EventService::emit($t,'invoice.created',['invoice_number'=>$num,'invoice_id'=>$iid,'total'=>$total],null,$ce->fetchColumn()?:null,'invoice');Response::json(['success'=>true,'message'=>'Invoice '.$num.' dibuat.','data'=>['redirect'=>url('/invoices/'.$iid)]]);}
    public function payment(string $id): void {$this->requireCsrf();if(!Auth::can('invoice.payment')&&!Auth::can('payment.create'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$amount=(float)Request::input('amount');if($amount<=0)Response::json(['success'=>false,'message'=>'Payment amount harus lebih dari 0.','errors'=>[]],422);$t=(int)Auth::tenantId();$db=Database::connection();$db->beginTransaction();try{$s=$db->prepare("SELECT * FROM invoices WHERE id=? AND tenant_id=? AND deleted_at IS NULL FOR UPDATE");$s->execute([(int)$id,$t]);$inv=$s->fetch();if(!$inv)throw new \RuntimeException('Invoice tidak ditemukan.');$balance=(float)$inv['balance'];if($amount>$balance+0.0001)throw new \RuntimeException('Payment melebihi outstanding balance '.money($balance).'.');$attachment=null;if(isset($_FILES['attachment'])&&($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK)$attachment=UploadService::store($_FILES['attachment'],$t,'invoices/'.$id.'/payments');$db->prepare("INSERT INTO payments(tenant_id,invoice_id,payment_date,amount,payment_method,bank,reference,attachment,notes,created_by,created_at) VALUES(?,?,COALESCE(?,CURDATE()),?,?,?,?,?,?,?,NOW())")->execute([$t,(int)$id,Request::input('payment_date')?:null,$amount,Request::input('payment_method','Bank Transfer'),Request::input('bank'),Request::input('reference'),$attachment,Request::input('notes'),Auth::id()]);$newPaid=(float)$inv['paid']+$amount;$newBal=max(0,(float)$inv['total']-$newPaid);$status=$newBal<=0.0001?'Paid':'Partial';$db->prepare("UPDATE invoices SET paid=?,balance=?,status=?,updated_by=?,updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$newPaid,$newBal,$status,Auth::id(),(int)$id,$t]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();Response::json(['success'=>false,'message'=>$e->getMessage(),'errors'=>[]],422);}ActivityService::log('invoice',(int)$id,'payment_received','Payment received',['amount'=>$amount]);EventService::emit($t,'payment.received',['invoice_number'=>$inv['invoice_number'],'invoice_id'=>(int)$id,'amount'=>$amount,'balance'=>$newBal],null,null,'payment_confirmation');Response::json(['success'=>true,'message'=>'Payment berhasil dicatat.','data'=>['reload'=>true]]);}

    public function reviewProof(string $id): void {$this->requireCsrf();if(!Auth::can('payment.create')&&!Auth::can('invoice.payment'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$action=(string)Request::input('action');if(!in_array($action,['approve','reject'],true))Response::json(['success'=>false,'message'=>'Action invalid.','errors'=>[]],422);$db=Database::connection();$t=(int)Auth::tenantId();$db->beginTransaction();try{$q=$db->prepare("SELECT pp.*,i.total,i.paid,i.balance,i.invoice_number FROM customer_payment_proofs pp JOIN invoices i ON i.id=pp.invoice_id AND i.tenant_id=pp.tenant_id WHERE pp.id=? AND pp.tenant_id=? AND pp.status='Pending' FOR UPDATE");$q->execute([(int)$id,$t]);$p=$q->fetch();if(!$p)throw new \RuntimeException('Payment proof tidak ditemukan.');if($action==='reject'){$db->prepare("UPDATE customer_payment_proofs SET status='Rejected',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND tenant_id=?")->execute([Auth::id(),(int)$id,$t]);$db->commit();Response::json(['success'=>true,'message'=>'Payment proof rejected.','data'=>['reload'=>true]]);}if((float)$p['amount']>(float)$p['balance']+0.0001)throw new \RuntimeException('Amount proof melebihi balance invoice saat ini.');$db->prepare("INSERT INTO payments(tenant_id,invoice_id,payment_date,amount,payment_method,bank,reference,attachment,notes,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW())")->execute([$t,$p['invoice_id'],$p['payment_date'],$p['amount'],$p['payment_method'],$p['bank'],$p['reference'],$p['attachment'],'Approved customer payment proof. '.($p['notes']??''),Auth::id()]);$newPaid=(float)$p['paid']+(float)$p['amount'];$newBalance=max(0,(float)$p['total']-$newPaid);$status=$newBalance<=0.0001?'Paid':'Partial';$db->prepare("UPDATE invoices SET paid=?,balance=?,status=?,updated_by=?,updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$newPaid,$newBalance,$status,Auth::id(),$p['invoice_id'],$t]);$db->prepare("UPDATE customer_payment_proofs SET status='Approved',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND tenant_id=?")->execute([Auth::id(),(int)$id,$t]);$db->commit();EventService::emit($t,'payment.received',['invoice_number'=>$p['invoice_number'],'invoice_id'=>$p['invoice_id'],'amount'=>$p['amount'],'balance'=>$newBalance]);}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();Response::json(['success'=>false,'message'=>$e->getMessage(),'errors'=>[]],422);}Response::json(['success'=>true,'message'=>'Payment proof approved and invoice updated.','data'=>['reload'=>true]]);}
    public function status(string $id): void {$this->requireCsrf();if(!Auth::can('invoice.create'))Response::json(['success'=>false,'message'=>'Forbidden','errors'=>[]],403);$status=(string)Request::input('status');if(!in_array($status,['Draft','Sent','Cancelled'],true))Response::json(['success'=>false,'message'=>'Status tidak valid.','errors'=>[]],422);Database::connection()->prepare("UPDATE invoices SET status=?,updated_by=?,updated_at=NOW() WHERE id=? AND tenant_id=? AND deleted_at IS NULL")->execute([$status,Auth::id(),(int)$id,Auth::tenantId()]);Response::json(['success'=>true,'message'=>'Invoice status diperbarui.','data'=>['reload'=>true]]);}
    private function forbidden(): void{http_response_code(403);require BASE_PATH.'/app/Views/errors/403.php';}
}
